// Generate NUL-terminated program name and version strings.
std::string name_s = FUZZ_PARAM_STR();
std::string ver_s  = FUZZ_PARAM_STR();
// Enforce requirements: both must be valid C strings (std::string::c_str() guarantees NUL termination).
const char *name_c = name_s.c_str();
const char *ver_c  = ver_s.c_str();
if (!name_c || !ver_c) { FUZZ_BAIL(); }

// Invoke the target function.
ovs_set_program_name(name_c, ver_c);

// Track that program identity has been initialized for other stubs.
FUZZ_SET_ATTR_INT_GLOBAL("prog_set", 1);
// (We do not output any objects; the API does not return or transfer ownership.)

// Ensure precondition: set a program name/version first if not already set.
if (!FUZZ_GET_ATTR_INT_GLOBAL("prog_set")) {
    std::string n = FUZZ_PARAM_STR();
    std::string v = FUZZ_PARAM_STR();
    ovs_set_program_name(n.c_str(), v.c_str());
    FUZZ_SET_ATTR_INT_GLOBAL("prog_set", 1);
}

// Invoke the target function. The returned pointer is read-only and not owned.
const char *ret = ovs_get_program_name();
// Do not modify or free 'ret'. We avoid asserting on content since behavior can be implementation-defined.
(void)ret; // silence unused warning in case instrumentation is off.

// Ensure precondition: set a program name/version first if not already set.
if (!FUZZ_GET_ATTR_INT_GLOBAL("prog_set")) {
    std::string n = FUZZ_PARAM_STR();
    std::string v = FUZZ_PARAM_STR();
    ovs_set_program_name(n.c_str(), v.c_str());
    FUZZ_SET_ATTR_INT_GLOBAL("prog_set", 1);
}

// Invoke the target function. The returned pointer is read-only and not owned.
const char *ret = ovs_get_program_version();
// Do not modify or free 'ret'.
(void)ret;

// Produce any boolean value and pass it to ovs_ignore().
bool b = (*FUZZ_PARAM(unsigned int) & 1u) != 0u;
ovs_ignore(b);
// No side effects expected; nothing to output.

// Exercise known properties and diverse inputs for is_pow2().
// Property 1: 0 is not a power of two.
FUZZ_ASSERT(!is_pow2((uintmax_t)0), "is_pow2(0) must be false");

// Property 2: Any single-bit value must be recognized as power of two.
unsigned int idx = *FUZZ_PARAM(unsigned int) % 63u; // use [0,62] to stay within 1<<idx in 64-bit
uint64_t single_bit = 1ull << idx;
FUZZ_ASSERT(is_pow2((uintmax_t)single_bit), "single-bit value must be power of two");

// Random input coverage.
uint64_t rnd = *FUZZ_PARAM(uint64_t);
volatile bool res = is_pow2((uintmax_t)rnd);
(void)res;

// Generate a valid json_type (excluding JSON_N_TYPES sentinel). Map a random byte to a valid enum.
unsigned int r = (unsigned int)(*FUZZ_PARAM(unsigned int));
static const int valid_types[] = {0, 1, 2, 3, 4, 5, 6, 7, 9};
int t = valid_types[r % (sizeof(valid_types)/sizeof(valid_types[0]))];
// Call the target. The returned pointer is static/owned by the library; do not free.
const char *name = json_type_to_string((enum json_type)t);
(void)name; // Consume to avoid unused warnings.

// Create a JSON null value.
struct json *jsonv = json_null_create();
if (!jsonv) { FUZZ_BAIL(); }
// Track type for downstream stubs.
FUZZ_SET_ATTR_INT(jsonv, "json_type", 0); /* JSON_NULL */

// Random boolean.
bool b = (*FUZZ_PARAM(unsigned int) % 2) != 0;
struct json *jsonv = json_boolean_create(b);
if (!jsonv) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(jsonv, "json_type", b ? 2 : 1); /* JSON_TRUE or JSON_FALSE */

// Build a NUL-terminated UTF-8 string without embedded NULs and limited size.
std::string raw = FUZZ_PARAM_STR();
if (raw.size() > 512) raw.resize(512);
std::string filtered;
filtered.reserve(raw.size());
for (char c : raw) { if (c != '\0') filtered.push_back(c); }
// Ensure at least an empty string is allowed; API copies and accepts UTF-8 (empty OK).
const char *cstr = filtered.c_str();
struct json *jsonv = json_string_create(cstr);
if (!jsonv) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(jsonv, "json_type", 7); /* JSON_STRING */

// Build a heap-allocated, NUL-terminated UTF-8 string with no embedded NULs.
std::string raw = FUZZ_PARAM_STR();
if (raw.size() > 512) raw.resize(512);
std::string filtered;
filtered.reserve(raw.size());
for (char c : raw) { if (c != '\0') filtered.push_back(c); }
// Allocate a buffer we will transfer ownership of; do not free after call.
size_t len = filtered.size();
