    FUZZ_ASSERT(in, "hmap_contains must be true for a node owned by the map");
}
// Conversely, if attributes say node is not in any map, a true result would be suspicious.
if (!attr_in && in) {
    // Don't assert hard since attributes may be stale; bail to guide corpus.
    FUZZ_BAIL();
}
// Output: return both inputs unchanged.

// Preconditions: map initialized.
if (!FUZZ_GET_ATTR_INT(hmap, "init")) { FUZZ_BAIL(); }
struct hmap_node *n = hmap_first(hmap);
// If last_count attribute exists, check empty/non-empty relation.
int last = FUZZ_GET_ATTR_INT(hmap, "last_count");
if (last == 0) { FUZZ_ASSERT(n == nullptr, "hmap_first should be NULL when last_count==0"); }
// Keep the map only.

// Preconditions: map initialized; node should be a valid node from this map and not freed.
if (!FUZZ_GET_ATTR_INT(hmap, "init")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(node, "in_map")) { FUZZ_BAIL(); }
void *owner = FUZZ_GET_ATTR_PTR(node, "owner");
if (owner != (void *)hmap) { FUZZ_BAIL(); }
struct hmap_node *n2 = hmap_next(hmap, node);
(void)n2; // May be NULL; not returned.
// Outputs: keep both inputs unchanged.

// Preconditions: map initialized; position is a valid pointer.
if (!FUZZ_GET_ATTR_INT(hmap, "init")) { FUZZ_BAIL(); }
// Initialize iterator position with fuzzed starting point.
struct hmap_position *p = pos;
p->bucket = (unsigned int)(*FUZZ_PARAM(unsigned int) & 0x7ff); // keep small to avoid long scans
p->offset = (unsigned int)(*FUZZ_PARAM(unsigned int) & 0xff);
// Iterate a single step to exercise API and state update.
struct hmap_node *n = hmap_at_position(hmap, p);
(void)n; // may be NULL
// Keep hmap and updated position for downstream use.

// Construct a fresh iterator position for hmap traversal.
// User-managed type: allocate and initialize modest bucket/offset to keep scans short.
struct hmap_position *pos = (struct hmap_position *)malloc(sizeof *pos);
if (!pos) { FUZZ_BAIL(); }
// Initialize with fuzzed starting point; keep small to avoid long scans.
pos->bucket = (unsigned int)(*FUZZ_PARAM(unsigned int) & 0x3ff); // 0..1023
pos->offset = (unsigned int)(*FUZZ_PARAM(unsigned int) & 0x3f);  // 0..63
// No special attributes required for this POD helper type.
// Output: pos persists for downstream use.

// Construct a standalone hmap_node. Although typically embedded, it can live on heap for fuzzing.
struct hmap_node *node = (struct hmap_node *)malloc(sizeof *node);
if (!node) { FUZZ_BAIL(); }
// Initialize fields: provide a hash value and ensure not linked to any map.
node->hash = (size_t)(*FUZZ_PARAM(unsigned long long));
