import random
import string
from typing import List

# Generator for hex-encoded string inputs suitable for ofpbuf_put_hex.
# The fuzzer stub calls FUZZ_PARAM_STR() once, so we return a bytes buffer
# containing an ASCII string with interesting, but valid hex sequences.
# Parser behavior: consumes hex digits (0-9a-fA-F), stops at first invalid.
# We therefore construct inputs that are fully valid for a long prefix, and
# sometimes include separators or an invalid terminator to explore stopping.

HEX_DIGITS_LOWER = '0123456789abcdef'
HEX_DIGITS_UPPER = '0123456789ABCDEF'
HEX_DIGITS_ALL = HEX_DIGITS_LOWER + HEX_DIGITS_UPPER
SEPARATORS = [" ", "\n", "\t", ":", "-", ","]
INVALID_TERMINATORS = ["G", "z", "_", "x", "X", "g", "Z", "~", "?", "/"]

# Some themed patterns to exercise parser behavior across lengths and cases.

def _repeat_pair(pair: str, n: int) -> str:
    return pair * n

def _alternating_case(n: int) -> str:
    # e.g., aA0Ff1E2d...
    out = []
    for i in range(n):
        d = random.choice(HEX_DIGITS_LOWER)
        out.append(d.upper() if i % 2 else d)
    return ''.join(out)

def _ascending_bytes_hex(n: int, start: int = 0) -> str:
    # 00 01 02 ... as hex without spaces
    return ''.join(f"{((start + i) & 0xFF):02x}" for i in range(n))

def _descending_bytes_hex(n: int, start: int = 255) -> str:
    return ''.join(f"{((start - i) & 0xFF):02X}" for i in range(n))

def _random_hex_len(n: int) -> str:
    return ''.join(random.choice(HEX_DIGITS_ALL) for _ in range(n))

def _with_separators(hexstr: str) -> str:
    # Insert separators between byte pairs occasionally. Many hex parsers
    # accept common separators; those that do not will stop at first one.
    out = []
    i = 0
    while i < len(hexstr):
        # Emit a pair
        take = min(2, len(hexstr) - i)
        out.append(hexstr[i:i+take])
        i += take
        # Occasionally insert a separator
        if i < len(hexstr) and random.random() < 0.25:
            out.append(random.choice(SEPARATORS))
    return ''.join(out)

def _maybe_make_odd_length(hexstr: str) -> str:
    # Sometimes drop last nibble to create odd number of hex digits
    if len(hexstr) > 0 and random.random() < 0.25:
        return hexstr[:-1]
    return hexstr

def _maybe_add_prefix(hexstr: str) -> str:
    # Some parsers accept 0x prefix per byte or overall. Try a few variants.
    mode = random.choice([0, 1, 2, 3])
    if mode == 0:
        return hexstr
    if mode == 1:
        # Overall 0x prefix
        return '0x' + hexstr
    if mode == 2:
        # Per-byte 0x prefixes sparsely
        out = []
        i = 0
        while i < len(hexstr):
            take = min(2, len(hexstr) - i)
            if take == 2 and random.random() < 0.4:
                out.append('0x')
            out.append(hexstr[i:i+take])
            i += take
        return ''.join(out)
    if mode == 3:
        # Mixed 0X and 0x prefixes
        out = []
        i = 0
        while i < len(hexstr):
            take = min(2, len(hexstr) - i)
            if take == 2 and random.random() < 0.3:
                out.append(random.choice(['0x','0X']))
            out.append(hexstr[i:i+take])
            i += take
        return ''.join(out)
    return hexstr

def _maybe_invalid_terminator(s: str) -> str:
    # Sometimes add an invalid character at end to test stop-at-first-invalid
    if random.random() < 0.35:
        return s + random.choice(INVALID_TERMINATORS)
    return s

def _build_candidates() -> List[str]:
    # Curated set of valid-heavy prefixes
    c = []
    # Short, edge, and empty
    c.append('')
    c.append('00')
    c.append('FF')
    c.append('0')  # odd nibble
    # Repeats
    c.append(_repeat_pair('00', 32))
    c.append(_repeat_pair('FF', 32))
    c.append(_repeat_pair('7F', 32))
    c.append(_repeat_pair('80', 32))
    # Ascending/descending sequences
    c.append(_ascending_bytes_hex(64))
    c.append(_descending_bytes_hex(64))
    # Alternating case random
    c.append(_alternating_case(128))
    # Random sizes around powers of two
    for n in [1,2,3,15,16,17,31,32,33,63,64,65,127,128,255,256,511,512,1023,1024]:
        # Limit to under 4096 bytes total; hex expands 2x.
        n_bytes = min(n, 1500)
        c.append(_random_hex_len(n_bytes * 2))
    return c


def generate(seed: int) -> bytes:
    random.seed(seed)

    candidates = _build_candidates()

    # Choose a base candidate and then decorate it with separators/prefixes,
    # and adjust length (odd/even), then maybe add an invalid terminator.
    base = random.choice(candidates)

    # With some probability, rebuild base as a structured pattern to diversify.
    if random.random() < 0.5:
        # Compose multiple segments to create mixed patterns.
        parts = []
        for _ in range(random.randint(2, 5)):
            kind = random.randint(0, 4)
            if kind == 0:
                parts.append(_ascending_bytes_hex(random.randint(4, 64)))
            elif kind == 1:
                parts.append(_descending_bytes_hex(random.randint(4, 64)))
            elif kind == 2:
                parts.append(_repeat_pair(random.choice(['00','FF','7F','80','01','10','F0']),
                                          random.randint(2, 32)))
            elif kind == 3:
                parts.append(_random_hex_len(random.randint(2, 128)))
            else:
                parts.append(_alternating_case(random.randint(2, 128)))
        base = ''.join(parts)

    # Ensure we don't exceed 4096 bytes output budget even after decorations.
    # Decorations add some characters; pre-trim the base if very large.
    max_len = 3800  # leave headroom for prefixes/separators/terminator
    if len(base) > max_len:
        base = base[:max_len]

    # Optionally insert separators and 0x prefixes.
    if random.random() < 0.7:
        base = _with_separators(base)
    if random.random() < 0.6:
        base = _maybe_make_odd_length(base)
    if random.random() < 0.6:
        base = _maybe_add_prefix(base)

    s = _maybe_invalid_terminator(base)

    # Final cap to 4096 bytes.
    s = s[:4096]

    return s.encode('ascii', errors='ignore')
